pub fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Problem statement assumes equal length, but we keep it safe and iterator-based.
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x & y)
        .collect()
}